# QQQ Mobile signed preview 1.0.0 - run this whole block in PowerShell.
# Connect ONE handheld by USB, enable USB debugging and accept its trust prompt.
& {
   $ErrorActionPreference = 'Stop'
   $release = 'https://git.kof22.com/QRun-IO/qqq-android/releases/tag/scanner-v1.0.0'
   $expected = 'EE5AC896B8985AF6F11B2E883955925D6571A2913D74A4AACCDB564B79394D51'
   $folder = Join-Path ([IO.Path]::GetTempPath()) ('qqq-mobile-' + [guid]::NewGuid())
   New-Item -ItemType Directory -Path $folder | Out-Null
   Invoke-WebRequest 'https://dl.google.com/android/repository/platform-tools-latest-windows.zip' -OutFile "$folder\tools.zip" -UseBasicParsing
   Expand-Archive -LiteralPath "$folder\tools.zip" -DestinationPath $folder
   $adb = Join-Path $folder 'platform-tools\adb.exe'
   Start-Process $release
   Write-Host 'Sign in on the release page and download QQQ-Mobile-1.0.0.apk to Downloads.'
   Read-Host 'After the download finishes, press Enter' | Out-Null
   $apk = Join-Path $env:USERPROFILE 'Downloads\QQQ-Mobile-1.0.0.apk'
   if(-not (Test-Path -LiteralPath $apk)) {
      $apk = (Read-Host 'Paste the full path of the downloaded QQQ-Mobile-1.0.0.apk').Trim('"')
   }
   if((Get-FileHash -LiteralPath $apk -Algorithm SHA256).Hash -ne $expected) {
      throw 'This file does not match the signed preview APK. Nothing installed.'
   }
   Read-Host 'Connect one handheld by USB. Enable USB debugging, unlock it and accept Allow USB debugging. Then press Enter' | Out-Null
   & $adb devices
   $serial = & $adb -d get-serialno
   if($LASTEXITCODE -ne 0 -or -not $serial -or $serial -eq 'unknown') {
      throw 'Connect exactly one USB handheld and accept its trust prompt, then rerun. No device changed.'
   }
   & $adb -s $serial install -r $apk
   if($LASTEXITCODE -ne 0) { throw 'Android refused installation. Do not uninstall or reset to bypass a signer mismatch; ask your administrator about migration.' }
   & $adb -s $serial shell am start -n 'io.qrun.mobile.scanner/.ScannerActivity'
   if($LASTEXITCODE -ne 0) { throw 'Installed, but could not open the app. Open QQQ Mobile on the handheld.' }
   Write-Host 'QQQ Mobile is open. Enter the HTTPS server address shown in Tools, sign in and request device approval.'
}

# QQQ Mobile signed preview 1.0.0 - paste this entire block into Terminal.
# Requires curl and unzip. Connect ONE handheld by USB and enable USB debugging.
(
   set -eu
   release='https://git.kof22.com/QRun-IO/qqq-android/releases/tag/scanner-v1.0.0'
   expected='ee5ac896b8985af6f11b2e883955925d6571a2913d74a4aaccdb564b79394d51'
   case "$(uname -s)" in
      Darwin) platform=darwin ;;
      Linux) platform=linux ;;
      *) printf '%s\n' 'Use the Windows PowerShell instructions on Windows.'; exit 1 ;;
   esac
   command -v curl >/dev/null || { printf '%s\n' 'Install curl with your operating system package manager first.'; exit 1; }
   command -v unzip >/dev/null || { printf '%s\n' 'Install unzip with your operating system package manager first.'; exit 1; }
   folder=$(mktemp -d "${TMPDIR:-/tmp}/qqq-mobile.XXXXXXXX")
   curl -fL "https://dl.google.com/android/repository/platform-tools-latest-$platform.zip" -o "$folder/tools.zip"
   unzip -q "$folder/tools.zip" -d "$folder"
   adb="$folder/platform-tools/adb"
   if [ "$platform" = darwin ]; then open "$release"; else xdg-open "$release" || printf 'Open this URL: %s\n' "$release"; fi
   printf '%s\n' 'Sign in on the release page. Download QQQ-Mobile-1.0.0.apk to Downloads.'
   printf '%s' 'Press Enter when finished, or enter its full path: '
   IFS= read -r apk
   apk=${apk:-"$HOME/Downloads/QQQ-Mobile-1.0.0.apk"}
   if [ "$platform" = darwin ]; then actual=$(shasum -a 256 "$apk"); else actual=$(sha256sum "$apk"); fi
   actual=${actual%% *}
   [ "$actual" = "$expected" ] || { printf '%s\n' 'APK checksum mismatch. Nothing installed.'; exit 1; }
   printf '%s\n' 'Connect one handheld by USB. Enable USB debugging, unlock it, and accept Allow USB debugging.'
   printf '%s' 'Press Enter when ready: '
   IFS= read -r ready
   "$adb" devices
   serial=$("$adb" -d get-serialno) || { printf '%s\n' 'Connect exactly one USB handheld and accept its trust prompt, then rerun.'; exit 1; }
   [ -n "$serial" ] && [ "$serial" != unknown ] || { printf '%s\n' 'No authorized USB handheld found.'; exit 1; }
   "$adb" -s "$serial" install -r "$apk" || { printf '%s\n' 'Android refused installation. Do not uninstall or reset to bypass a signer mismatch; ask your administrator about migration.'; exit 1; }
   "$adb" -s "$serial" shell am start -n io.qrun.mobile.scanner/.ScannerActivity
   printf '%s\n' 'QQQ Mobile is open. Enter the HTTPS server address from Tools, sign in and request approval.'
)

