# QQQ Print Client 1.0.1 - run this entire block in PowerShell.
# Downloads, verifies and installs the signed release, then opens setup.
& {
   $ErrorActionPreference = 'Stop'
   if(-not [Environment]::Is64BitOperatingSystem) { throw 'The Print Client requires 64-bit Windows.' }
   $release = 'https://github.com/QRun-IO/qqq-print-agent/releases/download/v1.0.1'
   $name = 'QqqPrintAgent-v1.0.1-x64.msi'
   $folder = Join-Path ([IO.Path]::GetTempPath()) ('qqq-print-' + [guid]::NewGuid())
   New-Item -ItemType Directory -Path $folder | Out-Null
   $msi = Join-Path $folder $name
   Invoke-WebRequest "$release/$name" -OutFile $msi -UseBasicParsing
   Invoke-WebRequest "$release/SHA256SUMS" -OutFile "$folder/SHA256SUMS" -UseBasicParsing
   $checksums = Get-Content -LiteralPath "$folder/SHA256SUMS" -Raw
   $pattern = '(?m)^([a-fA-F0-9]{64})\s+\*?' + [regex]::Escape($name) + '\s*$'
   $match = [regex]::Match([string]$checksums, $pattern)
   if(-not $match.Success) { throw 'The release has no matching MSI checksum. Nothing installed.' }
   if((Get-FileHash -LiteralPath $msi -Algorithm SHA256).Hash -ne $match.Groups[1].Value) {
      throw 'Installer checksum mismatch. Nothing installed.'
   }
   $signature = Get-AuthenticodeSignature -LiteralPath $msi
   if($signature.Status -ne 'Valid' -or
      $signature.SignerCertificate.GetNameInfo([Security.Cryptography.X509Certificates.X509NameType]::SimpleName, $false) -ne 'James Maes') {
      throw 'Installer publisher verification failed. Nothing installed.'
   }
   $install = Start-Process msiexec.exe -Verb RunAs -Wait -PassThru -ArgumentList @('/i', ('"' + $msi + '"'), '/norestart')
   if($install.ExitCode -notin @(0, 3010)) { throw "Windows Installer failed or was cancelled (code $($install.ExitCode))." }
   if($install.ExitCode -eq 3010) { Write-Host 'Installation succeeded. Windows requires a restart; restart when convenient.' }
   $app = Join-Path $env:ProgramFiles 'QQQ Print Agent\App\Qqq.PrintAgent.exe'
   if(Test-Path -LiteralPath $app) { Start-Process -FilePath $app -Verb RunAs }
   else { Write-Host 'Installed. Open QQQ Print Agent from the Windows Start menu.' }
}
